def cap(f):
    try:
        v = f()
        return v if v is not None else 'ok'
    except Exception as e:
        return type(e).__name__

s = sol.UndoStack()
result = [cap(lambda: s.pop()), cap(lambda: s.peek()), cap(lambda: s.undo()), len(s)]

import random
rnd = random.Random(0)
s = sol.UndoStack()
log = []
for i in range(3000):
    op = rnd.random()
    if op < 0.5:
        s.push(i)
    elif op < 0.8:
        if len(s):
            log.append(s.pop())
        else:
            log.append("empty")
    else:
        try:
            s.undo()
            log.append("undo")
        except RuntimeError:
            log.append("nothing")
    if i % 300 == 0:
        log.append([len(s), s.peek() if len(s) else None])
tail = []
for _ in range(5):
    if len(s):
        tail.append(s.pop())
result = [log[:120], log[-120:], len(log), len(s), tail]

